MB.COMBOS.forEach((c) => { c.items = [].concat(c.item); c.id = c.char + '+' + c.items[0]; });
MB.combosOf = (id) => MB.COMBOS.filter((c) => c.char === id || c.items.includes(id));

// alternate outfits that aren't real clothes, kept out of the wardrobe
MB.HIDDEN_COSTUMES = { 'james-lone': ['phone-james'], 'hayley-kate': ['hurt'] };

MB.STARTER_LEADERS = ['hayley-kate', 'james-lone', 'maiko-ghan', 'luther-jones'];

// Rarity drives card frames, drop odds, reveal effects and how many copies a deck may hold (a card's own
// `copies` overrides it). Only the starter deck's cards are owned at the start; everything else, commons included,
// is pieced together from the fragments in card packs: `shards` of them unlock the card (weights are relative among
// still-locked rarities).
MB.RARITY = {
  common:    { name: 'Common',    color: '#c9d1dc', stars: 1, weight: 50, copies: 2, shards: 2 },
  rare:      { name: 'Rare',      color: '#4aa3ff', stars: 2, weight: 30, copies: 2, shards: 4 },
  epic:      { name: 'Epic',      color: '#b35cff', stars: 3, weight: 14, copies: 2, shards: 6 },
  legendary: { name: 'Legendary', color: '#ffc93c', stars: 4, weight: 6, copies: 1, shards: 9 },
  token:     { name: 'Token',     color: '#888888', stars: 0, weight: 0 },
  bond:      { name: 'Fusion',    color: '#ff5fa2', stars: 4, weight: 0 },
};

// Card levels: once you own a character card, more 🧩 fragments of it (from packs, the Shop or crafting) level it up,
// from Lv 1 to Lv `max`. `cost[rarity][L - 1]` fragments take it from Lv L to L + 1, and `gain[rarity][L - 1]` is the
// [ATK, HP] that step adds for good: rarer cards need more fragments and grow more. At the top level a card earns its
// special move. Item cards don't level. Your levels count in Story and quick battles, not in the Arena.
MB.LEVELS = {
  max: 5,
  cost: { common: [1, 2, 3, 4], rare: [2, 3, 4, 5], epic: [2, 4, 5, 7], legendary: [3, 5, 7, 9] },
  gain: {
    common:    [[0, 1], [1, 0], [0, 1], [1, 0]],
    rare:      [[0, 1], [1, 0], [0, 1], [1, 1]],
    epic:      [[1, 0], [0, 1], [1, 1], [1, 1]],
    legendary: [[1, 1], [0, 1], [1, 1], [1, 2]],
  },
};

// Packs are earned by winning and opened from the Packs screen. Each slot is a bundle of fragments of one
// card of at least that rarity ('card' = any): mostly cards you don't own yet, otherwise characters you can still
// level up (MB.LEVELS). MB.SHARD_DROP says how many fragments a bundle holds.
// Profile pictures aren't in packs: they are won in Story (MB.stageAvatars, js/collection.js).
MB.PACKS = {
  common: { name: 'Common Pack', color: '#c9d1dc', slots: ['card', 'card', 'card'] },
  rare:   { name: 'Rare Pack',   color: '#4aa3ff', slots: ['rare', 'rare', 'card', 'card'] },
  epic:   { name: 'Epic Pack',   color: '#b35cff', slots: ['epic', 'epic', 'rare', 'card', 'card'] },
};
MB.SHARD_DROP = { card: 1, rare: 2, epic: 3 };
MB.STARTER_AVATAR = 'hayley';

// Legacy starter and tutorial rival deck; new saves roll commons with this cost curve (MB.Collection.starterDeck).
MB.STARTER_DECK = [
  'julie-hunley', 'julie-hunley', 'school-bag', 'school-bag', 'towel',
  'rimu-hiraga', 'rimu-hiraga', 'keiko-ghan', 'keiko-ghan', 'luther-jones', 'luther-jones',
  'isabella-hunley', 'isabella-hunley', 'walking-stick', 'james-lone', 'james-lone',
  'wert-lone', 'wert-lone', 'farley-kate', 'farley-kate',
];
// Original starter cards, retained for legacy saves and content checks.
MB.STARTER_CARDS = [...new Set(MB.STARTER_DECK)];

